-- ====================================================================
-- Apon Somaj — Migration 001: Bangladesh Administrative Location Hierarchy
-- Standard 5-Tier Administrative Hierarchy (COMPLETE & OFFICIAL):
-- Bangladesh -> Division (8) -> District (64) -> Upazila/Thana (517) -> Union/Paurashava (4,623) -> Ward (41,607+)
-- ====================================================================

-- 1. Enable pg_trgm extension for fast bilingual search
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 2. Divisions Table (8 Administrative Divisions)
CREATE TABLE IF NOT EXISTS public.divisions (
    id TEXT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    bn_name VARCHAR(100) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 3. Districts Table (64 Administrative Districts)
CREATE TABLE IF NOT EXISTS public.districts (
    id TEXT PRIMARY KEY,
    division_id TEXT NOT NULL REFERENCES public.divisions(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    bn_name VARCHAR(100) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 4. Upazilas / Thanas Table (All 494 Upazilas + Metropolitan Police Thanas)
CREATE TABLE IF NOT EXISTS public.upazilas (
    id TEXT PRIMARY KEY,
    district_id TEXT NOT NULL REFERENCES public.districts(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    bn_name VARCHAR(100) NOT NULL,
    is_thana BOOLEAN NOT NULL DEFAULT false,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 5. Unions / Paurashavas Table (All 4,623 Official Unions & Paurashavas)
CREATE TABLE IF NOT EXISTS public.unions (
    id TEXT PRIMARY KEY,
    upazila_id TEXT NOT NULL REFERENCES public.upazilas(id) ON DELETE CASCADE,
    name VARCHAR(150) NOT NULL,
    bn_name VARCHAR(150) NOT NULL,
    is_paurashava BOOLEAN NOT NULL DEFAULT false,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 6. Wards Table (All Administrative Wards across Unions & Paurashavas)
CREATE TABLE IF NOT EXISTS public.wards (
    id TEXT PRIMARY KEY,
    union_id TEXT NOT NULL REFERENCES public.unions(id) ON DELETE CASCADE,
    number INT NOT NULL,
    name VARCHAR(150) NOT NULL,
    bn_name VARCHAR(150) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ====================================================================
-- Indexes for High-Performance Geographic Queries & Cascading Lookups
-- ====================================================================
CREATE INDEX IF NOT EXISTS idx_districts_division_id ON public.districts(division_id);
CREATE INDEX IF NOT EXISTS idx_districts_name ON public.districts(name);
CREATE INDEX IF NOT EXISTS idx_districts_bn_name ON public.districts(bn_name);

CREATE INDEX IF NOT EXISTS idx_upazilas_district_id ON public.upazilas(district_id);
CREATE INDEX IF NOT EXISTS idx_upazilas_name ON public.upazilas(name);
CREATE INDEX IF NOT EXISTS idx_upazilas_bn_name ON public.upazilas(bn_name);

CREATE INDEX IF NOT EXISTS idx_unions_upazila_id ON public.unions(upazila_id);
CREATE INDEX IF NOT EXISTS idx_unions_name ON public.unions(name);
CREATE INDEX IF NOT EXISTS idx_unions_bn_name ON public.unions(bn_name);

CREATE INDEX IF NOT EXISTS idx_wards_union_id ON public.wards(union_id);
CREATE INDEX IF NOT EXISTS idx_wards_number ON public.wards(number);

-- Trigram Indexes for Instant Bilingual Location Autocomplete & Search
CREATE INDEX IF NOT EXISTS idx_districts_search_trgm ON public.districts USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_upazilas_search_trgm ON public.upazilas USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_unions_search_trgm ON public.unions USING gin (name gin_trgm_ops);

-- ====================================================================
-- Row Level Security (RLS) Policies
-- ====================================================================
ALTER TABLE public.divisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.districts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.upazilas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.unions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wards ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'divisions' AND policyname = 'Allow public read access to divisions') THEN
        CREATE POLICY "Allow public read access to divisions" ON public.divisions FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'districts' AND policyname = 'Allow public read access to districts') THEN
        CREATE POLICY "Allow public read access to districts" ON public.districts FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'upazilas' AND policyname = 'Allow public read access to upazilas') THEN
        CREATE POLICY "Allow public read access to upazilas" ON public.upazilas FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'unions' AND policyname = 'Allow public read access to unions') THEN
        CREATE POLICY "Allow public read access to unions" ON public.unions FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'wards' AND policyname = 'Allow public read access to wards') THEN
        CREATE POLICY "Allow public read access to wards" ON public.wards FOR SELECT USING (true);
    END IF;
END $$;

