-- ====================================================================
-- SEED DATA: All 41,607+ Applicable Wards (Ward 1 to Ward 9 for every Union)
-- Constitutionally & Administratively, every Bangladesh Union has 9 Wards.
-- Generated idempotently for all active Unions.
-- ====================================================================
INSERT INTO public.wards (id, union_id, number, name, bn_name, active)
SELECT 
  'w-' || u.id || '-' || s.n AS id,
  u.id AS union_id,
  s.n AS number,
  'Ward ' || s.n AS name,
  CASE s.n
    WHEN 1 THEN '১ নং ওয়ার্ড'
    WHEN 2 THEN '২ নং ওয়ার্ড'
    WHEN 3 THEN '৩ নং ওয়ার্ড'
    WHEN 4 THEN '৪ নং ওয়ার্ড'
    WHEN 5 THEN '৫ নং ওয়ার্ড'
    WHEN 6 THEN '৬ নং ওয়ার্ড'
    WHEN 7 THEN '৭ নং ওয়ার্ড'
    WHEN 8 THEN '৮ নং ওয়ার্ড'
    WHEN 9 THEN '৯ নং ওয়ার্ড'
    ELSE s.n || ' নং ওয়ার্ড'
  END AS bn_name,
  true AS active
FROM public.unions u
CROSS JOIN generate_series(1, 9) AS s(n)
ON CONFLICT (id) DO NOTHING;
